<?php
    $usuarios = \App\Models\User::query()->with('equipos')->orderBy('name')->get();
    $usuariosModalData = $usuarios->map(fn ($u) => [
        'id' => $u->id, 'name' => $u->name, 'email' => $u->email, 'rol' => $u->rol,
        'activo' => (bool) $u->activo, 'isSelf' => $u->id === auth()->id(),
        'equipos' => $u->equipos->pluck('nombre')->values()->all(),
        'createdAt' => optional($u->created_at)->format('d/m/Y H:i'),
    ])->values();
    $usuarioModalError = $usuariosModalData->firstWhere('id', (int) old('user_edit_id'));
    if ($usuarioModalError && old('name')) { $usuarioModalError['name'] = old('name'); }
    if ($usuarioModalError && old('email')) { $usuarioModalError['email'] = old('email'); }
    if ($usuarioModalError && old('rol')) { $usuarioModalError['rol'] = old('rol'); }
?>
<div class="aduana-module-view" x-data="{
    modalOpen:<?php echo \Illuminate\Support\Js::from($errors->any())->toHtml() ?>, modalMode:<?php echo \Illuminate\Support\Js::from(old('user_edit_id') ? 'edit' : (old('nombres') !== null ? 'create' : 'details'))->toHtml() ?>, selectedUser:<?php echo \Illuminate\Support\Js::from($usuarioModalError)->toHtml() ?>, search:'', users:<?php echo \Illuminate\Support\Js::from($usuariosModalData)->toHtml() ?>, nombres:<?php echo \Illuminate\Support\Js::from(old('nombres',''))->toHtml() ?>, apellidos:<?php echo \Illuminate\Support\Js::from(old('apellidos',''))->toHtml() ?>,
    open(mode,user=null){this.modalMode=mode;this.selectedUser=user?{...user}:null;this.modalOpen=true;}, close(){this.modalOpen=false;this.selectedUser=null;},
    filteredUsers(){const q=this.search.trim().toLowerCase();return this.users.filter(u=>!q||[u.name,u.email,u.rol].join(' ').toLowerCase().includes(q));},
    updateUrl(){return <?php echo \Illuminate\Support\Js::from(route('admin.usuarios.update',0))->toHtml() ?>.replace(/\/0$/,'/'+this.selectedUser.id);},
    suspendUrl(){return <?php echo \Illuminate\Support\Js::from(route('admin.usuarios.suspend',0))->toHtml() ?>.replace(/\/0\/suspend$/,'/'+this.selectedUser.id+'/suspend');},
    activateUrl(){return <?php echo \Illuminate\Support\Js::from(route('admin.usuarios.activate',0))->toHtml() ?>.replace(/\/0\/activate$/,'/'+this.selectedUser.id+'/activate');},
    deleteUrl(){return <?php echo \Illuminate\Support\Js::from(route('admin.usuarios.destroy',0))->toHtml() ?>.replace(/\/0$/,'/'+this.selectedUser.id);},
    previewEmail(){const slug=(v)=>{const m={'á':'a','à':'a','ä':'a','â':'a','é':'e','è':'e','ë':'e','ê':'e','í':'i','ì':'i','ï':'i','î':'i','ó':'o','ò':'o','ö':'o','ô':'o','ú':'u','ù':'u','ü':'u','û':'u','ñ':'n','ç':'c'};return(v.trim().split(/\s+/)[0]||'').toLowerCase().split('').map(c=>m[c]||c).join('').replace(/[^a-z0-9]/g,'');};const base=(slug(this.nombres)||'nombre')+'.'+(slug(this.apellidos)||'apellido')+'@aduanasim.com';let email=base;let suffix=1;while(this.users.some(u=>u.email.toLowerCase()===email.toLowerCase())){suffix++;email=base.replace('@aduanasim.com',suffix+'@aduanasim.com');}return email;}
}" @keydown.escape.window="close()">
