    <?php if(session('error')): ?><div class="aduana-notice" style="margin-bottom:1rem;border-color:#b45309;"><span class="aduana-notice__icon">!</span><div><strong><?php echo e(session('error')); ?></strong></div></div><?php endif; ?>
