        <template x-for="u in filteredUsers()" :key="u.id"><tr style="border-bottom:1px solid #e5e7eb;"><td style="padding:.85rem 1rem;"><strong x-text="u.name"></strong><div style="font-size:.83rem;color:#71818B;margin-top:.2rem;" x-text="u.email"></div><span x-show="u.isSelf" style="font-size:.75rem;color:#64748b;">Tu cuenta</span></td><td style="padding:.85rem 1rem;"><span class="aduana-role-chip" x-text="u.rol.charAt(0).toUpperCase()+u.rol.slice(1)"></span></td><td style="padding:.85rem 1rem;font-size:.88rem;" x-text="u.rol==='capturista'?(u.equipos.length?u.equipos.join(', '):'Sin equipo'):'—'"></td><td style="padding:.85rem 1rem;"><span :style="u.activo?'color:#059669;font-weight:600':'color:#b45309;font-weight:600'" x-text="u.activo?'Activo':'Suspendido'"></span></td><td style="padding:.85rem 1rem;text-align:right;white-space:nowrap;"><button type="button" class="aduana-text-action" @click="open('details',u)" style="background:none;border:0;cursor:pointer;margin-right:.3rem;">Gestión completa</button><button type="button" class="aduana-text-action" @click="open('edit',u)" style="background:none;border:0;cursor:pointer;">Editar</button></td></tr></template>
