            <div x-show="modalMode==='details'&&selectedUser"><div style="padding:.9rem;background:#f8fafc;border-radius:.7rem;margin-bottom:1rem;"><strong style="font-size:1.1rem;" x-text="selectedUser.name"></strong><div style="color:#64748b;margin-top:.2rem;" x-text="selectedUser.email"></div></div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:.7rem;"><div style="padding:.75rem;border:1px solid #e5e7eb;border-radius:.6rem;"><small style="color:#64748b;">Rol</small><div style="font-weight:600;text-transform:capitalize;" x-text="selectedUser.rol"></div></div><div style="padding:.75rem;border:1px solid #e5e7eb;border-radius:.6rem;"><small style="color:#64748b;">Estado</small><div style="font-weight:600;" x-text="selectedUser.activo?'Activo':'Suspendido'"></div></div><div style="padding:.75rem;border:1px solid #e5e7eb;border-radius:.6rem;"><small style="color:#64748b;">Registro</small><div style="font-weight:600;" x-text="selectedUser.createdAt||'Sin dato'"></div></div><div style="padding:.75rem;border:1px solid #e5e7eb;border-radius:.6rem;"><small style="color:#64748b;">Equipo(s)</small><div style="font-weight:600;" x-text="selectedUser.equipos.length?selectedUser.equipos.join(', '):'—'"></div></div></div><div style="display:flex;flex-wrap:wrap;justify-content:flex-end;gap:.6rem;margin-top:1.2rem;"><button type="button" @click="open('edit',selectedUser)" style="border:1px solid #cbd5e1;background:#fff;padding:.6rem .9rem;border-radius:.5rem;cursor:pointer;">Editar</button><template x-if="!selectedUser.isSelf"><button type="button" @click="open(selectedUser.activo?'suspend':'activate',selectedUser)" style="border:1px solid #cbd5e1;background:#fff;padding:.6rem .9rem;border-radius:.5rem;cursor:pointer;" x-text="selectedUser.activo?'Suspender':'Reactivar'"></button></template><button type="button" @click="open('delete',selectedUser)" style="border:1px solid #fecaca;color:#b91c1c;background:#fff;padding:.6rem .9rem;border-radius:.5rem;cursor:pointer;">Eliminar</button></div></div>

            <div x-show="modalMode==='edit'&&selectedUser"><form method="POST" :action="updateUrl()"><?php echo csrf_field(); ?> <?php echo method_field('PUT'); ?><input type="hidden" name="user_edit_id" :value="selectedUser.id"><label style="display:block;margin-bottom:.9rem;">Nombre completo<input name="name" required maxlength="255" x-model="selectedUser.name" style="display:block;width:100%;margin-top:.3rem;padding:.65rem;border:1px solid #cbd5e1;border-radius:.5rem;"></label><label style="display:block;margin-bottom:.9rem;">Correo<input name="email" type="email" required x-model="selectedUser.email" style="display:block;width:100%;margin-top:.3rem;padding:.65rem;border:1px solid #cbd5e1;border-radius:.5rem;"></label><template x-if="selectedUser.isSelf&&selectedUser.rol==='admin'"><input type="hidden" name="rol" value="admin"></template><label style="display:block;margin-bottom:1rem;">Rol<select name="rol" x-model="selectedUser.rol" :disabled="selectedUser.isSelf&&selectedUser.rol==='admin'" style="display:block;width:100%;margin-top:.3rem;padding:.65rem;border:1px solid #cbd5e1;border-radius:.5rem;"><option value="admin">Admin</option><option value="agente">Agente</option><option value="capturista">Capturista</option></select></label><p x-show="selectedUser.isSelf&&selectedUser.rol==='admin'" style="font-size:.82rem;color:#64748b;">Puedes editar tus datos; tu rol Admin se mantiene para evitar perder el acceso.</p><div style="display:flex;justify-content:flex-end;gap:.6rem;margin-top:1rem;"><button type="button" @click="close()" style="background:none;border:0;cursor:pointer;">Cancelar</button><button type="submit" style="background:#233147;color:#fff;padding:.65rem 1rem;border:0;border-radius:.5rem;cursor:pointer;font-weight:600;">Guardar cambios</button></div></form></div>

            <div x-show="(modalMode==='suspend'||modalMode==='activate')&&selectedUser"><p x-text="modalMode==='suspend'?'¿Confirmas que deseas suspender el acceso de esta cuenta?':'¿Confirmas que deseas reactivar esta cuenta?'"></p><div style="margin:1rem 0;padding:.9rem;background:#f8fafc;border-radius:.6rem;"><strong x-text="selectedUser.name"></strong><div style="color:#64748b;" x-text="selectedUser.email"></div></div><form method="POST" :action="modalMode==='suspend'?suspendUrl():activateUrl()"><?php echo csrf_field(); ?><input type="hidden" name="_method" value="PATCH"><div style="display:flex;justify-content:flex-end;gap:.6rem;margin-top:1rem;"><button type="button" @click="close()" style="background:none;border:0;cursor:pointer;">Cancelar</button><button type="submit" :style="modalMode==='suspend'?'background:#b45309;color:white':'background:#059669;color:white'" style="padding:.65rem 1rem;border:0;border-radius:.5rem;cursor:pointer;font-weight:600;" x-text="modalMode==='suspend'?'Suspender cuenta':'Reactivar cuenta'"></button></div></form></div>

            <div x-show="modalMode==='delete'&&selectedUser"><p style="color:#991b1b;font-weight:600;">Esta acción es permanente y no se puede deshacer.</p><p x-text="selectedUser.isSelf?'Estás eliminando tu propia cuenta. La sesión se cerrará inmediatamente.':'¿Deseas eliminar esta cuenta?"></p><div style="margin:1rem 0;padding:.9rem;background:#fef2f2;border:1px solid #fecaca;border-radius:.6rem;"><strong x-text="selectedUser.name"></strong><div style="color:#991b1b;" x-text="selectedUser.email"></div></div><form method="POST" :action="deleteUrl()"><?php echo csrf_field(); ?> <?php echo method_field('DELETE'); ?><div style="display:flex;justify-content:flex-end;gap:.6rem;margin-top:1rem;"><button type="button" @click="close()" style="background:none;border:0;cursor:pointer;">Cancelar</button><button type="submit" style="background:#dc2626;color:#fff;padding:.65rem 1rem;border:0;border-radius:.5rem;cursor:pointer;font-weight:600;">Eliminar definitivamente</button></div></form></div>
